	function generateParticles(count, seed) {
		const particles = [];
		for (let i = 0; i < count; i++) {
			const angle = i / count * Math.PI * 2 + seed;
			const distance = 50 + i % 5 * 30;
			particles.push({
				x: Math.cos(angle) * distance,
				y: Math.sin(angle) * distance,
				size: 2 + i % 4 * 2,
				delay: i % 8 * .05
			});
		}
		return particles;
	}
